// Extract message data from 360dialog or Twilio format
const body = $input.first().json.body || $input.first().json;

let phoneNumber, messageBody, messageTimestamp, messageId;

// 360dialog format
if (body.messages && body.messages.length > 0) {
  const msg = body.messages[0];
  phoneNumber = msg.from;
  messageBody = msg.text?.body || msg.body || '';
  messageTimestamp = msg.timestamp;
  messageId = msg.id;
}
// Twilio format
else if (body.From || body.WaId) {
  phoneNumber = (body.From || '').replace('whatsapp:', '').replace('+', '');
  messageBody = body.Body || '';
  messageTimestamp = Math.floor(Date.now() / 1000).toString();
  messageId = body.MessageSid || '';
}
// Direct/test format
else if (body.phone && body.message) {
  phoneNumber = body.phone.replace('+', '');
  messageBody = body.message;
  messageTimestamp = Math.floor(Date.now() / 1000).toString();
  messageId = 'test-' + Date.now();
}
else {
  throw new Error('Unknown webhook format');
}

// Normalize Moroccan phone numbers
if (phoneNumber.startsWith('212')) {
  // already correct
} else if (phoneNumber.startsWith('0')) {
  phoneNumber = '212' + phoneNumber.substring(1);
}

return [{
  json: {
    phoneNumber,
    messageBody,
    messageTimestamp,
    messageId,
    receivedAt: new Date().toISOString()
  }
}];

// Check if phone number has an active session
// Using n8n static data as key-value store
const phone = $input.first().json.phoneNumber;
const staticData = $getWorkflowStaticData('global');

// Initialize sessions store if not exists
if (!staticData.sessions) {
  staticData.sessions = {};
}

const session = staticData.sessions[phone];
const now = Date.now();
const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes

let isActiveSession = false;
let currentState = 'new';
let conversationHistory = [];
let sessionData = {};

if (session && (now - session.lastActivity) < SESSION_TIMEOUT) {
  // Active session found
  isActiveSession = true;
  currentState = session.state;
  conversationHistory = session.history || [];
  sessionData = session.data || {};

  // Update last activity
  staticData.sessions[phone].lastActivity = now;
} else {
  // New session or expired
  staticData.sessions[phone] = {
    state: 'new',
    lastActivity: now,
    startedAt: now,
    history: [],
    data: {}
  };
}

// Add current message to history
conversationHistory.push({
  role: 'user',
  content: $input.first().json.messageBody,
  timestamp: $input.first().json.messageTimestamp
});

staticData.sessions[phone].history = conversationHistory;

return [{
  json: {
    ...$input.first().json,
    isActiveSession,
    currentState,
    conversationHistory,
    sessionData
  }
}];

// Send reply back via 360dialog WhatsApp API
const response = $input.first().json;
const phone = response.phoneNumber;
const replyText = response.replyText;

return [{
  json: {
    phone,
    replyText,
    status: 'processed'
  }
}];
